  await expect(panel).toContainText('candidate_b_broader_scope_selector_use_unselected_scope_class');
  await expect(panel).toContainText('Only exact classes selected by a server-owned runtime receipt are admitted.');
  expect(runtimePayloads).toHaveLength(3);
  expect(selectorUsePayloads).toHaveLength(3);
  expect(selectorUseStatusPayloads).toHaveLength(1);
  expect(selectorActivationPayloads).toHaveLength(2);
  expect(activationConsumptionPayloads).toHaveLength(3);
  expect(consumptionReceiptUsePayloads).toHaveLength(3);
  expect(consumptionReceiptUseStatusPayloads).toHaveLength(1);
  expect(operatorRepeatabilityTrialPayloads).toHaveLength(2);
