test('Layer 3 workbench renders raw-mixed handoff delivery readiness honestly (server-backed)', async ({ page, request }) => {
  const session = await prepareRawMixedHandoffDeliverySession(request);

  // Assert the full downstream chain reached the expected server-backed states
  expect(session.handoffPrepare.handoff_export_state).toBe('handoff_export_prepared');
  expect(session.apsDispatch.aps_handoff_state).toBe('aps_handoff_dispatched');
  expect(session.downloadPrepare.external_export_download_state).toBe('external_export_download_prepared');
  expect(session.signedReference.signed_reference_state).toBe('external_export_download_signed_reference_ready');
  expect(session.signedReference.signed_reference_token_id).toBeTruthy();
  expect(session.signedReference.signed_reference_receipt_id).toBeTruthy();

  // Safety surfaces: confirm flags remain closed (no flag was silently enabled)
  expect(session.handoffPrepare.aps_handoff_enabled).not.toBe(true);
  if (session.downloadPrepare.browser_download_enabled !== undefined) {
    expect(session.downloadPrepare.browser_download_enabled).toBe(false);
  }
  if (session.signedReference.signed_url_enabled !== undefined) {
    expect(session.signedReference.signed_url_enabled).toBe(false);
  }

  // Navigate to the workbench and attach the session
  await page.goto('/review/layer3');
  await attachSessionToWorkbench(page, session.seed.session_id, ['dataset_version', 'aps_content_document']);

  // After reload, recoverSessionFromStorage() fetches /session/{id} and sets
  // State.sessionSummary before renderAll(). Waiting on page.waitForResponse
  // and then calling response.json() races with Chromium freeing the body on
  // domcontentloaded ("No resource with given identifier"). Instead, reload
  // and then poll State.sessionSummary directly — it is set by the recovery
  // handler and is the definitive signal that recovery+render is complete.
  // (State is a top-level const in a classic script, not window.State.)
  await page.reload({ waitUntil: 'domcontentloaded' });
  await page.waitForFunction(
    (id) => typeof State !== 'undefined' && State.sessionSummary?.session_id === id,
    session.seed.session_id,
  );
  const sessionSummary = await page.evaluate(() => State.sessionSummary);

  // Prove the workbench restores this fully-downstream session honestly after reload
  expect(sessionSummary.session_id).toBe(session.seed.session_id);
  // The session summary must carry all downstream sub-objects so the page can restore
  // correct step controls — a session_id-only response would leave controls in an
  // indeterminate state and silently break operator continuity after reload.
  expect(sessionSummary.handoff_export_prepare).toBeTruthy();
  expect(sessionSummary.aps_handoff_dispatch).toBeTruthy();
  expect(sessionSummary.external_export_download).toBeTruthy();
  // Signed-reference state must survive reload so the operator can still use the reference
  expect(sessionSummary.external_export_download?.signed_reference_state).toBe(
    'external_export_download_signed_reference_ready',
  );
});

test('Layer 3 signed reference use fails closed on invalid token (server-backed)', async ({ request }) => {
  // A garbage token string fails at the HMAC signature check — the endpoint never reaches DB or delivery.
  const result = await request.post(
    '/api/v1/layer3/handoff/export/download/signed-reference/use',
    { data: { signed_reference_token: 'not.a.valid.token' } },
  );
  expect([400, 409]).toContain(result.status());
  const body = await result.json();
  expect(body.error_code).toMatch(/^external_export_download_signed_reference/);
});

test('Layer 3 signed reference replay is denied with 409 (server-backed)', async ({ request }) => {
  const session = await prepareRawMixedHandoffDeliverySession(request);
  const token = session.signedReference.signed_reference_token;
  // First use must succeed and deliver the artifact
  const first = await request.post(
    '/api/v1/layer3/handoff/export/download/signed-reference/use',
    { data: { signed_reference_token: token } },
  );
  expect(first.status()).toBe(200);
  expect(first.headers()['x-layer3-signed-reference-state']).toBe(
    'external_export_download_signed_reference_delivered',
  );
  // Immediate replay of the same token must be denied
  const replay = await request.post(
    '/api/v1/layer3/handoff/export/download/signed-reference/use',
    { data: { signed_reference_token: token } },
  );
  expect(replay.status()).toBe(409);
  const body = await replay.json();
  expect(body.error_code).toBe('external_export_download_signed_reference_replay_denied');
});

